  color: var(--green-primary);
  font-weight: 600;
}

.redemption-section {
  padding: 80px 0;
}

.redemption-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 15px;
  background: var(--cream-light);
  color: var(--text-dark);
  transition: all var(--transition);
  border: 2px solid transparent;
}

.tab-btn:hover {
  background: var(--cream);
}

.tab-btn.active {
  background: var(--green-primary);
  color: var(--white);
}

.redemption-content {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
  padding: 48px;
  display: none;
}

.redemption-content.active {
  display: block;
}

.redemption-content h3 {
  font-size: 28px;
  color: var(--green-dark);
  margin-bottom: 8px;
}

.redemption-content .stars-value {
  font-size: 18px;
  color: var(--green-primary);
  font-weight: 600;
  margin-bottom: 16px;
}

.redemption-content p {
  font-size: 16px;
  color: var(--text-muted);
}

.partnerships-section {
  padding: 80px 0;
  background: var(--cream-light);
}

.partnerships-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.partnership-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  align-items: center;
  gap: 24px;
}

.partnership-logo {
  width: 80px;
  height: 80px;
  background: var(--cream);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--green-dark);
  flex-shrink: 0;
}

.partnership-info h4 {
  font-size: 20px;
  color: var(--green-dark);
  margin-bottom: 8px;
}

.partnership-info p {
  font-size: 14px;
  color: var(--text-muted);
}

/* Gift Page */
.gift-hero {
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  padding: 80px 0;
  text-align: center;
}

.gift-hero h1 {
  font-size: 48px;
  color: var(--green-dark);
  margin-bottom: 16px;
}

.gift-hero p {
  font-size: 18px;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
}

.carousel-section {
  padding: 64px 0;
}

.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.carousel-header h2 {
  font-size: 28px;
  color: var(--green-dark);
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--green-primary);
  color: var(--green-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.carousel-btn:hover {
  background: var(--green-primary);
  color: var(--white);
}

.carousel {
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform 0.5s ease;
}

.gift-card {
  flex: 0 0 calc(25% - 18px);
  min-width: 250px;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}

.gift-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.gift-card-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-muted);
}

.gift-card-info {
  padding: 20px;
}

.gift-card-info h4 {
  font-size: 16px;
  color: var(--green-dark);
  margin-bottom: 8px;
}

.gift-card-info p {
  font-size: 13px;
  color: var(--text-muted);
}

.category-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.business-section {
  padding: 80px 0;
  background: var(--cream-light);
}

.business-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.business-content h2 {
  font-size: 32px;
  color: var(--green-dark);
  margin-bottom: 16px;
}

.business-content p {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.faq-section {
  padding: 80px 0;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-light);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-dark);
  text-align: left;
}

.faq-question::after {
  content: '+';
  font-size: 24px;
  color: var(--green-primary);
  transition: transform var(--transition);
}

.faq-item.open .faq-question::after {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 24px;
  font-size: 15px;
  color: var(--text-muted);
  line-height: 1.8;
}

/* Store Locator */
.locator-hero {
  background: var(--green-dark);
  padding: 48px 0;
  color: var(--white);
  text-align: center;
}

.locator-hero h1 {
  font-size: 40px;
  color: var(--white);
  margin-bottom: 8px;
}

.locator-controls {
  background: var(--white);
  padding: 24px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  margin-top: -40px;
  position: relative;
  z-index: 10;
}

.controls-row {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
}

.order-type-toggle {
  display: flex;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 2px solid var(--green-primary);
}

.toggle-btn {
  padding: 12px 24px;
  font-weight: 600;
  background: var(--white);
  color: var(--green-primary);
  transition: all var(--transition);
}

.toggle-btn.active {
  background: var(--green-primary);
  color: var(--white);
}

.search-input {
  flex: 1;
  display: flex;
  gap: 12px;
}

.search-input input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  font-size: 15px;
  transition: border-color var(--transition);
}

.search-input input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.filter-btn {
  padding: 12px 24px;
  border-radius: var(--radius-md);
  background: var(--cream-light);
  color: var(--text-dark);
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all var(--transition);
}

.filter-btn:hover {
  background: var(--cream);
}

.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  gap: 24px;
  padding: 32px 0;
}

.store-list {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}

.store-item {
  padding: 20px;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  transition: background var(--transition);
}

.store-item:hover,
.store-item.active {
  background: var(--cream-light);
}

.store-item h4 {
  font-size: 16px;
  color: var(--green-dark);
  margin-bottom: 4px;
}

.store-item p {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.store-features {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.feature-tag {
  padding: 4px 8px;
  background: var(--cream-light);
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-muted);
}

.map-container {
  background: var(--cream-light);
  border-radius: var(--radius-lg);
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* Filter Panel */
.filter-panel {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 16px;
  box-shadow: var(--shadow-sm);
  display: none;
}

.filter-panel.show {
  display: block;
}

.filter-group {
  margin-bottom: 20px;
}

.filter-group h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--text-dark);
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-chip {
  padding: 8px 16px;
  border-radius: var(--radius-lg);
  background: var(--cream-light);
  font-size: 14px;
  transition: all var(--transition);
  cursor: pointer;
}

.filter-chip:hover,
.filter-chip.active {
  background: var(--green-primary);
  color: var(--white);
}

/* Responsive */
@media (max-width: 1024px) {
  .hero .container {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero h1 {
    font-size: 40px;
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .promo-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-nav {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .tiers-grid {
    grid-template-columns: 1fr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
  }

  .business-card {
    grid-template-columns: 1fr;
  }

  .locator-layout {
    grid-template-columns: 1fr;
  }

  .gift-card {
    flex: 0 0 calc(33.333% - 16px);
  }
}

@media (max-width: 768px) {
  .nav-main {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero {
    padding: 48px 0;
  }

  .hero h1 {
    font-size: 32px;
  }

  .section {
    padding: 48px 0;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .promo-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-col {
    display: none;
  }

  .footer-col:first-child {
    display: block;
  }

  .footer-accordion {
    display: block;
  }

  .footer-accordion-btn {
    width: 100%;
    padding: 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 14px;
    font-weight: 600;
    color: var(--white);
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }

  .footer-accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-accordion.open .footer-accordion-content {
    max-height: 300px;
  }

  .footer-accordion-content li {
    padding: 8px 16px;
  }

  .carousel-track {
    gap: 16px;
  }

  .gift-card {
    flex: 0 0 calc(50% - 12px);
  }

  .redemption-tabs {
    gap: 4px;
  }

  .tab-btn {
    padding: 8px 16px;
    font-size: 13px;
  }

  .controls-row {
    flex-direction: column;
  }

  .order-type-toggle {
    width: 100%;
  }

  .toggle-btn {
    flex: 1;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .gift-card {
    flex: 0 0 100%;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .cookie-actions {
    width: 100%;
    justify-content: center;
  }
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in {
  animation: fadeIn 0.6s ease forwards;
}

/* App Download Section */
.app-section {
  padding: 80px 0;
  background: var(--green-primary);
  color: var(--white);
  text-align: center;
}

.app-section h2 {
  font-size: 36px;
  color: var(--white);
  margin-bottom: 16px;
}

.app-section p {
  font-size: 18px;
  opacity: 0.9;
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.app-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.app-btn {
  background: var(--white);
  color: var(--green-dark);
  padding: 12px 24px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  transition: all var(--transition);
}

.app-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

/* Terms Section */
.terms-section {
  padding: 48px 0;
  background: var(--cream-light);
}

.terms-content {
  max-width: 800px;
  margin: 0 auto;
}

.terms-content h3 {
  font-size: 20px;
  color: var(--green-dark);
  margin: 24px 0 12px;
}

.terms-content p,
.terms-content li {
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.8;
}

.terms-content ul {
  padding-left: 24px;
  margin-bottom: 16px;
}

/* Placeholder Images */
.placeholder-img {
  background: linear-gradient(135deg, var(--cream) 0%, #E8D5B5 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 14px;
  text-align: center;
  padding: 20px;
}

.placeholder-img.large {
  width: 100%;
  height: 300px;
  border-radius: var(--radius-lg);
}

.placeholder-img.square {
  width: 100%;
  height: 200px;
  border-radius: var(--radius-md);
}
